import assert from 'node:assert/strict';
import {Miniflare,convertV4MiniflareOptions} from 'miniflare';
import {build} from 'esbuild';

// Uses the bundle generated by check:worker. No credentials, deployment, or remote GitHub calls.
const runtime=new Miniflare(convertV4MiniflareOptions({modules:true,scriptPath:'.worker-build/index.js',compatibilityDate:'2026-10-13',durableObjects:{SECURITY:{className:'ProbeSecurity',useSQLite:true}},bindings:{ALLOWED_ORIGIN:'https://pgt.example',DATA_BRANCH:'main'}}));
try{
  const unauthorized=await runtime.dispatchFetch('http://localhost/api/probe/users/a@example.com/json');
  const unknown=await runtime.dispatchFetch('http://localhost/api/unknown');
  assert.equal(unauthorized.status,401);assert.equal(unknown.status,404);
  assert.deepEqual(await unauthorized.json(),{error:'PGT_SESSION_REQUIRED'});
  console.log('Runtime Worker/SQLite DO local: sesión ausente 401; endpoint inexistente 404.');
}finally{await runtime.dispose();}

// Execute the adapter using workerd's native fetch and an intercepted outbound service.
// This catches runtime-specific RequestInit errors that Node fetch mocks cannot detect.
const bundled=await build({stdin:{contents:`
  import {GithubContentsStorage} from './worker/storage.ts';
  export default {async fetch(request){
    if(new URL(request.url).pathname==='/old-options'){
      try{new Request('https://api.github.com',{redirect:'error'});return Response.json({supported:true});}
      catch(error){return Response.json({supported:false,name:error.name,invalidRedirect:/Invalid redirect value/.test(error.message)});}
    }
    if(new URL(request.url).pathname==='/old-receiver'){
      try{const holder={transport:fetch};await holder.transport('https://api.github.com',{redirect:'manual'});return Response.json({supported:true});}
      catch(error){return Response.json({supported:false,name:error.name,invalidReceiver:/Illegal invocation|incorrect.*this/i.test(error.message)});}
    }
    try{await new GithubContentsStorage('synthetic-runtime-token').verifyPrivate();return Response.json({ok:true});}
    catch(error){return Response.json({error:error.message},{status:error.status||500});}
  }};`,resolveDir:process.cwd()},bundle:true,write:false,format:'esm',target:'es2022'});
let mode='success',outgoing=0;
const githubRuntime=new Miniflare(convertV4MiniflareOptions({modules:true,script:bundled.outputFiles[0].text,compatibilityDate:'2026-10-13',outboundService:async request=>{
  outgoing++;
  assert.equal(request.url,'https://api.github.com/repos/dmda92/pgt-bjj-data');
  assert.equal(request.headers.get('Authorization'),'Bearer synthetic-runtime-token');
  if(mode==='redirect')return new Response(null,{status:302,headers:{Location:'https://unexpected.example/never-follow'}});
  if(mode==='unauthorized')return new Response('{}',{status:401});
  return Response.json({private:true,full_name:'dmda92/pgt-bjj-data'});
}}));
try{
  const old=await(await githubRuntime.dispatchFetch('http://localhost/old-options')).json();
  assert.deepEqual(old,{supported:false,name:'TypeError',invalidRedirect:true});assert.equal(outgoing,0);
  const receiver=await(await githubRuntime.dispatchFetch('http://localhost/old-receiver')).json();
  assert.deepEqual(receiver,{supported:false,name:'TypeError',invalidReceiver:true});assert.equal(outgoing,0);
  const success=await githubRuntime.dispatchFetch('http://localhost/fixed-options');assert.equal(success.status,200);assert.deepEqual(await success.json(),{ok:true});assert.equal(outgoing,1);
  mode='redirect';const redirect=await githubRuntime.dispatchFetch('http://localhost/fixed-options');assert.equal(redirect.status,503);assert.deepEqual(await redirect.json(),{error:'DATA_REDIRECT_REJECTED'});assert.equal(outgoing,2);
  mode='unauthorized';const denied=await githubRuntime.dispatchFetch('http://localhost/fixed-options');assert.equal(denied.status,503);assert.deepEqual(await denied.json(),{error:'DATA_TOKEN_INVALID_OR_EXPIRED'});assert.equal(outgoing,3);
  console.log('Runtime fetch nativo: receptor y redirect originales reproducidos; petición corregida OK; redirect bloqueado; 401 distinguido. Sin conexiones externas.');
}finally{await githubRuntime.dispose();}
